// SLUG SORT — sort-puzzle (Cat Arcade v2)
// Tubes of stacked coloured slugs. Tap a tube to lift its top pool, tap another to pour.
// Levels are generated by reverse-shuffling a solved state (so every level is always solvable)
// and then double-checked by a real DFS solver before the player ever sees it.
// Feel: real arc pours with squash/stretch, splash on landing, a clink per slug, a chime +
// confetti when a tube completes, and a full celebration when the board is sorted.
import {
  makeGame, sfx, music, comboPitch, clamp, lerp, rnd, ri, chance, R, TAU,
  rr, circle, hexA, fmt, ease, smooth,
} from '../_vendor/gp2x.js';

const W = 540, H = 960;
const g = makeGame({
  id: 'sort-puzzle', title: 'SLUG SORT', sub: 'SORT EVERY TUBE',
  hook: 'one colour per tube', w: W, h: H, bg: '#070b18', style: 'toon',
  bloom: .95, ca: .35, vig: 1, scan: .14,
});
const P = new URLSearchParams(location.search);
const isAuto = P.has('auto');

/* ------------------------------------------------------------------ tuning */
const CAP = 4;                    // slugs per tube
const WINLVL = 4;                 // levels cleared = win
const RIM = 11;                   // glass thickness above the bottom of the liquid
const SLUG_COLS = ['#ff4d6d', '#4c7bff', '#4ee06a', '#ffd23f', '#b96bff', '#35e0ff', '#ff9d3c'];
const LEVELS = [
  { tubes: 3, colors: 2, shuffles: 9 },
  { tubes: 4, colors: 3, shuffles: 14 },
  { tubes: 5, colors: 3, shuffles: 18 },
  { tubes: 5, colors: 4, shuffles: 22 },
  { tubes: 6, colors: 4, shuffles: 26 },
  { tubes: 6, colors: 5, shuffles: 30 },
];

/* ------------------------------------------------------------------ state */
let tubes = [];            // [[colourIdx,...], ...] bottom-first
let geom = [];             // per-tube rects
let anim = [];             // per-tube {shake, sel, glow, done, lift}
let fly = [];              // slugs in flight
let sel = -1;
let levelIdx, score, movesLeft, phase, levelT, winT, autoT, t, botT, sol, solI, musicOn;
let ui = {};

function mulberry32(a) {
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let x = Math.imul(a ^ (a >>> 15), 1 | a);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

/* ------------------------------------------------------------------ level generation (reverse shuffle => always solvable) */
const isSolved = st => st.every(tb => tb.length === 0 || (tb.length === CAP && tb.every(c => c === tb[0])));
const tubeKey = st => st.map(tb => tb.join('')).sort().join('|');

function genLevel(cfg, tag) {
  for (let attempt = 0; attempt < 24; attempt++) {
    const rng = mulberry32(1337 + tag * 977 + attempt * 7919);
    const st = [];
    for (let c = 0; c < cfg.colors; c++) st.push(new Array(CAP).fill(c));
    for (let e = cfg.colors; e < cfg.tubes; e++) st.push([]);
    for (let k = 0; k < cfg.shuffles; k++) {
      const opts = [];
      for (let i = 0; i < st.length; i++) {
        const s = st[i]; if (!s.length) continue;
        const col = s[s.length - 1];
        let run = 1;
        while (s.length - 1 - run >= 0 && s[s.length - 1 - run] === col) run++;
        for (let j = 0; j < st.length; j++) {
          if (i === j) continue;
          const d = st[j];
          if (d.length >= CAP) continue;
          if (!d.length) continue;                       // only pour onto liquid: keeps the mess spread out
          if (d[d.length - 1] !== col) continue;
          if (run === s.length && d.length + run <= CAP) continue;  // don't just move whole pools around
          opts.push([i, j]);
        }
      }
      if (!opts.length) break;
      const [i, j] = opts[Math.floor(rng() * opts.length)];
      const col = st[i][st[i].length - 1];
      let run = 1;
      while (st[i].length - 1 - run >= 0 && st[i][st[i].length - 1 - run] === col) run++;
      const n = Math.min(run, CAP - st[j].length);
      for (let q = 0; q < n; q++) st[j].push(st[i].pop());
    }
    if (isSolved(st)) continue;
    if (st.some(tb => tb.length === CAP && tb.every(c => c === tb[0]))) continue;
    const solution = solveLevel(st);
    if (solution && solution.length) return { st, solution };
  }
  // paranoid fallback: a hand-made legal board
  const st = [[0, 1, 0, 1], [1, 0, 1, 0], []];
  return { st, solution: solveLevel(st) || [] };
}

/* DFS with a canonical-state memo + greedy move ordering. Tiny boards, so it's instant. */
function solveLevel(start) {
  const path = [];
  const seen = new Set();
  let nodes = 0;
  const dfs = (st, depth) => {
    if (isSolved(st)) return true;
    if (depth <= 0) return false;
    if (++nodes > 120000) return false;
    const k = tubeKey(st);
    if (seen.has(k)) return false;
    seen.add(k);
    const moves = [];
    for (let i = 0; i < st.length; i++) {
      const s = st[i]; if (!s.length) continue;
      if (s.length === CAP && s.every(c => c === s[0])) continue;   // already finished
      const col = s[s.length - 1];
      let run = 1;
      while (s.length - 1 - run >= 0 && s[s.length - 1 - run] === col) run++;
      for (let j = 0; j < st.length; j++) {
        if (i === j) continue;
        const d = st[j];
        if (d.length >= CAP) continue;
        if (d.length && d[d.length - 1] !== col) continue;
        if (!d.length && run === s.length) continue;                // pointless whole-pool shuffle
        let sc = 0;
        if (d.length) sc += 12 + (d.length + run <= CAP ? 6 : 0);
        else sc -= 6;
        if (d.length + Math.min(run, CAP - d.length) === CAP && d.every(c => c === col)) sc += 25;
        if (d.length === CAP) sc += 20;
        moves.push({ i, j, sc });
      }
    }
    moves.sort((a, b) => b.sc - a.sc);
    for (const m of moves) {
      const nst = st.map(tb => tb.slice());
      const col = nst[m.i][nst[m.i].length - 1];
      let run = 1;
      while (nst[m.i].length - 1 - run >= 0 && nst[m.i][nst[m.i].length - 1 - run] === col) run++;
      const n = Math.min(run, CAP - nst[m.j].length);
      for (let q = 0; q < n; q++) nst[m.j].push(nst[m.i].pop());
      path.push([m.i, m.j]);
      if (dfs(nst, depth - 1)) return true;
      path.pop();
    }
    return false;
  };
  return dfs(start.map(tb => tb.slice()), 42) ? path.slice() : null;
}

/* ------------------------------------------------------------------ layout */
function layoutFor(n) {
  const cols = n <= 3 ? n : (n === 4 ? 2 : (n <= 6 ? 3 : 4));
  const rows = Math.ceil(n / cols);
  const TW = cols <= 2 ? 110 : (cols === 3 ? 84 : 68);
  const TH = rows === 1 ? 300 : (cols <= 2 ? 252 : (cols === 3 ? 226 : 196));
  const GX = cols <= 1 ? 0 : (cols === 2 ? 58 : (cols === 3 ? 40 : 24));
  const GY = 80;
  const totalH = rows * TH + (rows - 1) * GY;
  const y0 = 318 + (580 - totalH) / 2;
  const out = [];
  for (let i = 0; i < n; i++) {
    const r = Math.floor(i / cols), c = i % cols;
    const inRow = Math.min(cols, n - r * cols);
    const rowW = inRow * TW + (inRow - 1) * GX;
    out.push({ x: (W - rowW) / 2 + c * (TW + GX), y: y0 + r * (TH + GY), w: TW, h: TH });
  }
  return out;
}

const slugH = G => (G.h - RIM * 2) / CAP;
const slotPos = (i, slot) => {
  const G = geom[i], sh = slugH(G);
  return { x: G.x + G.w / 2, y: G.y + G.h - RIM - (slot + 0.5) * sh, h: sh, w: G.w - 10 };
};

/* ------------------------------------------------------------------ world reset */
function resetWorld() {
  levelIdx = 0; score = 0; phase = 'play'; levelT = 0; winT = 0; autoT = 0; t = 0; botT = 0;
  fly = []; sel = -1;
  ui = { levelPop: 0, movePop: 0, nudge: 0 };
  g.score = 0; g.combo.reset(); g.fx.clear();
  setupLevel();
}

function setupLevel() {
  const cfg = LEVELS[Math.min(levelIdx, LEVELS.length - 1)];
  const { st, solution } = genLevel(cfg, levelIdx);
  tubes = st;
  geom = layoutFor(tubes.length);
  anim = tubes.map(() => ({ shake: 0, glow: 0, done: 0, lift: 0, wob: rnd(0, TAU) }));
  sel = -1; fly = [];
  sol = solution; solI = 0;
  movesLeft = Math.max(cfg.shuffles + 7, (sol ? sol.length : 8) + 6);
  phase = 'play';
  g.state = { level: levelIdx + 1, moves: movesLeft, phase: 'play', prog: +(levelIdx / WINLVL).toFixed(3) };
  ui.levelPop = 1; g.tween(ui, 'levelPop', 0, .35);
  g.showBanner(`LEVEL ${levelIdx + 1}`, .9);
  sfx('unlock', { pitch: .9 + levelIdx * .05 });
  g.flash('#8ff3ff', .12); g.punch(.02);
  updateState();
}

function updateState() {
  g.state.level = levelIdx + 1;
  g.state.moves = movesLeft;
  g.state.phase = phase;
  g.state.prog = +clamp((levelIdx + (isSolved(tubes) ? 1 : 0)) / WINLVL, 0, 1).toFixed(3);
  g.state.sorted = tubes.filter(tb => tb.length === CAP && tb.every(c => c === tb[0])).length;
  g.state.free = tubes.filter(tb => !tb.length).length;
}

/* ------------------------------------------------------------------ pouring */
function tapTube(i) {
  if (phase !== 'play' || i < 0 || i >= tubes.length) return false;
  if (sel < 0) {
    if (!tubes[i].length) { reject(i); return false; }
    if (tubes[i].length === CAP && tubes[i].every(c => c === tubes[i][0])) { reject(i); return false; }
    sel = i;
    sfx('click', { pitch: 1.05 });
    anim[i].glow = 1;
    const p = slotPos(i, tubes[i].length - 1);
    g.fx.emit('ring', p.x, p.y, { r: 26, size: 26, life: .3, color: hexA(SLUG_COLS[tubes[i][tubes[i].length - 1]], .8) });
    g.punch(.006);
    return true;
  }
  if (sel === i) {
    sel = -1;
    sfx('tick', { vol: .4 });
    return false;
  }
  return pour(sel, i);
}

function pour(a, b) {
  const src = tubes[a], dst = tubes[b];
  if (!src.length) { sel = -1; return false; }
  const col = src[src.length - 1];
  if (dst.length >= CAP || (dst.length && dst[dst.length - 1] !== col)) {
    reject(b);
    return false;
  }
  let run = 1;
  while (src.length - 1 - run >= 0 && src[src.length - 1 - run] === col) run++;
  const n = Math.min(run, CAP - dst.length);
  const srcLen = src.length, dstLen = dst.length;
  // launch the flying slugs from the top of the source to the destination slots
  for (let k = 0; k < n; k++) {
    const A = slotPos(a, srcLen - 1 - k), B = slotPos(b, dstLen + k);
    fly.push({
      col, x: A.x, y: A.y, x0: A.x, y0: A.y, x1: B.x, y1: B.y,
      t: -k * 0.055, dur: 0.24, w: A.w, h: A.h,
      peak: 60 + Math.abs(A.x - B.x) * .18, rot: 0, sx: 1, sy: 1,
    });
  }
  // update the logic immediately (the visuals chase it — keeps taps snappy)
  for (let k = 0; k < n; k++) dst.push(src.pop());
  sel = -1;
  movesLeft -= 1;
  ui.movePop = 1; g.tween(ui, 'movePop', 0, .25);
  sfx('pour', { pitch: 1 + (g.combo.n * .04), vol: .8 });
  g.shake(1.6); g.punch(.006);
  const pts = 10 * Math.max(1, Math.round(n)) + (g.combo.n * 2);
  score += pts;
  g.score = score;
  g.state.moves = movesLeft;

  // tube completed?
  if (dst.length === CAP && dst.every(c => c === col)) completeTube(b);
  else sfx('splash', { pitch: .9 + rnd(0, .2), vol: .35 });

  updateState();
  if (isSolved(tubes)) levelClear();
  else if (movesLeft <= 0) outOfMoves();
  return true;
}

function reject(i) {
  anim[i].shake = 1;
  sfx('snap', { pitch: .8, vol: .8 });
  g.shake(4); g.flash('#ff4d6d', .10); g.hitstop(.02);
  const G = geom[i];
  g.fx.burst(G.x + G.w / 2, G.y + 20, 6, { kind: 'spark', color: '#ff4d6d', speed: 120, life: .25, size: 2.6, g: 300 });
  g.popup('NOPE', G.x + G.w / 2, G.y + 6, '#ff8ca0', 20);
}

function completeTube(i) {
  anim[i].done = 1;
  anim[i].glow = 1;
  const G = geom[i], cx = G.x + G.w / 2, cy = G.y + G.h / 2;
  const col = SLUG_COLS[tubes[i][0]];
  score += 250 + levelIdx * 50;
  g.score = score;
  sfx('ding', { pitch: 1 + i * .03 }); sfx('perfect', { pitch: 1.05, vol: .6 });
  g.showBanner('SORTED!', .85);
  g.flash(hexA(col, .5), .2);
  g.punch(.045); g.shake(7); g.hitstop(.05);
  g.combo.hit(cx, G.y - 18, '+');
  g.fx.blast(cx, cy, { r: 60, color: col, colors: [col, '#ffffff', '#ffe6a8'], n: 20, speed: 220, flashA: .12, punch: .02, shake: 4 });
  g.fx.emit('ring', cx, G.y + 10, { r: 50, size: 44, life: .5, color: col });
  for (let k = 0; k < 10; k++) {
    g.fx.emit('confetti', cx + rnd(-24, 24), G.y + rnd(0, 40), {
      vx: rnd(-170, 170), vy: rnd(-260, -80), g: 620, life: rnd(.6, 1.1),
      size: rnd(4, 9), color: chance(.4) ? '#ffffff' : col, rot: rnd(0, TAU), vr: rnd(-12, 12), drag: .6,
    });
  }
  g.popup('SORTED', cx, G.y - 26, col, 26);
}

function levelClear() {
  phase = 'clear'; levelT = 1.15;
  score += 600 + levelIdx * 300;
  g.score = score;
  sfx('fanfare'); sfx('win', { pitch: 1.06, vol: .8 });
  g.flash('#ffffff', .5); g.hitstop(.14); g.slowmo(.4, .5);
  g.punch(.07); g.shake(14);
  g.showBanner(levelIdx + 1 >= WINLVL ? 'ALL SORTED!' : 'LEVEL CLEAR', 1.4);
  for (let k = 0; k < 34; k++) {
    g.fx.emit('confetti', rnd(20, W - 20), rnd(-60, 120), {
      vx: rnd(-140, 140), vy: rnd(-120, 120), g: 420, life: rnd(1.2, 2.2),
      size: rnd(5, 11), color: SLUG_COLS[ri(0, SLUG_COLS.length - 1)], rot: rnd(0, TAU), vr: rnd(-11, 11), drag: .4,
    });
  }
  g.fx.emit('ring', W / 2, 560, { r: 160, size: 120, life: .8, color: '#ffffff' });
  for (let i = 0; i < tubes.length; i++) anim[i].glow = 1;
  g.state.phase = 'clear';
  updateState();
}

function outOfMoves() {
  phase = 'over';
  sfx('lose', { vol: .8 }); sfx('groan', { vol: .6 });
  g.flash('#ff3b5c', .35); g.shake(16); g.hitstop(.08);
  g.showBanner('OUT OF MOVES', 1.2);
  const done = clamp((levelIdx + (isSolved(tubes) ? 1 : 0)) / WINLVL, 0, .95);
  g.end({ win: false, score: Math.round(score), label: 'SCORE', progress: done });
}

/* ------------------------------------------------------------------ bot (drives the very same tap path) */
function botStep(dt) {
  if (phase !== 'play') return;
  botT -= dt;
  if (botT > 0) return;
  const dumb = g.dumb();
  if (dumb) {
    // deliberate nonsense: tap random tubes until the move budget burns out
    const i = ri(0, tubes.length - 1);
    tapTube(i);
    botT = .085;
    return;
  }
  if (!sol || solI >= sol.length) {
    sol = solveLevel(tubes); solI = 0;
    if (!sol || !sol.length) { botT = .3; return; }
  }
  const [a, b] = sol[solI];
  // route through the ordinary selection path
  if (sel !== a) { tapTube(a); botT = .05; return; }
  const before = tubeKey(tubes);
  tapTube(b);
  if (tubeKey(tubes) === before) { sol = solveLevel(tubes); solI = 0; }   // state drifted — re-plan
  else solI++;
  botT = .075;
}

/* ------------------------------------------------------------------ update */
function update(dt) {
  if (dt <= 0) return;
  t += dt;
  if (!musicOn) { musicOn = true; music('puzzle'); }
  if (phase === 'play') autoT += dt;

  // per-tube anims
  for (let i = 0; i < tubes.length; i++) {
    const a = anim[i];
    a.shake = Math.max(0, a.shake - dt * 4.5);
    a.glow = Math.max(0, a.glow - dt * 2.2);
    const wantLift = sel === i ? 1 : 0;
    a.lift = lerp(a.lift, wantLift, 1 - Math.pow(.0015, dt));
  }

  // flying slugs follow their arc
  for (let k = fly.length - 1; k >= 0; k--) {
    const f = fly[k];
    f.t += dt;
    if (f.t < 0) continue;
    const u = Math.min(1, f.t / f.dur);
    const e = u;
    f.x = lerp(f.x0, f.x1, e);
    f.y = lerp(f.y0, f.y1, e) - Math.sin(e * Math.PI) * f.peak;
    const vx = (f.x1 - f.x0), vy = (f.y1 - f.y0) - Math.cos(e * Math.PI) * f.peak * Math.PI;
    f.rot = clamp(Math.atan2(vy, Math.abs(vx) + 40) * .5, -.5, .5);
    const sp = Math.min(1, Math.hypot(vx, vy) / 400);
    f.sx = 1 + sp * .18; f.sy = 1 - sp * .18;
    if (u >= 1) {
      // splash landing
      const col = SLUG_COLS[f.col];
      g.fx.emit('ring', f.x1, f.y1 - f.h * .35, { r: 22, size: 18, life: .26, color: hexA(col, .8) });
      g.fx.burst(f.x1, f.y1 - f.h * .3, 5, { kind: 'spark', color: [col, '#ffffff'], speed: 110, life: .24, size: 2.6, g: 320, ang: -Math.PI / 2, spread: 2.4 });
      sfx('glass', { pitch: 1.5 + rnd(-.15, .25), vol: .22 });
      fly.splice(k, 1);
    }
  }

  if (isAuto) botStep(dt);

  // taps / clicks
  for (const p of g.taps) {
    for (let i = 0; i < geom.length; i++) {
      const G = geom[i];
      if (p.x > G.x - 14 && p.x < G.x + G.w + 14 && p.y > G.y - 40 && p.y < G.y + G.h + 16) { tapTube(i); break; }
    }
  }

  for (let i = 0; i < tubes.length; i++) {
    const a = anim[i];
    if (a.done > 0 && Math.random() < dt * 2.2) {
      const G = geom[i];
      g.fx.emit('spark', G.x + rnd(6, G.w - 6), G.y + rnd(20, G.h - 10), { vx: rnd(-14, 14), vy: rnd(-30, -8), life: .5, size: 2.4, color: '#ffffff', add: true });
    }
  }

  if (phase === 'clear') {
    levelT -= dt;
    if (Math.random() < dt * 10) {
      g.fx.emit('confetti', rnd(20, W - 20), -20, { vx: rnd(-80, 80), vy: rnd(60, 170), g: 260, life: rnd(1.1, 1.9), size: rnd(4, 10), color: SLUG_COLS[ri(0, SLUG_COLS.length - 1)], rot: rnd(0, TAU), vr: rnd(-10, 10), drag: .4 });
    }
    if (levelT <= 0) {
      if (levelIdx + 1 >= WINLVL) { winSequence(); }
      else { levelIdx++; setupLevel(); }
    }
    return;
  }
  if (phase === 'win') {
    winT -= dt;
    if (Math.random() < dt * 16) {
      g.fx.emit('confetti', rnd(16, W - 16), -20, { vx: rnd(-90, 90), vy: rnd(70, 200), g: 240, life: rnd(1.2, 2.1), size: rnd(5, 11), color: SLUG_COLS[ri(0, SLUG_COLS.length - 1)], rot: rnd(0, TAU), vr: rnd(-12, 12), drag: .4 });
    }
    if (winT <= 0) g.end({ win: true, score: Math.round(score), label: 'SCORE', progress: 1 });
    return;
  }
  if (phase !== 'play') return;

  if (isAuto) {
    if (g.dumb() && autoT > 15) { outOfMoves(); }
  }
  updateState();
}

function winSequence() {
  phase = 'win'; winT = 1.3;
  sfx('fanfare'); sfx('unlock', { pitch: 1.2 });
  g.flash('#ffffff', .7); g.hitstop(.18); g.slowmo(.32, 1.1);
  g.punch(.09); g.shake(20);
  g.showBanner('PERFECTLY SORTED!', 1.6);
  g.fx.blast(W / 2, 560, { r: 220, color: '#ffffff', colors: ['#35e0ff', '#ffd23f', '#4ee06a', '#ff4d6d', '#b96bff', '#ffffff'], n: 55, speed: 360, flashA: .3, punch: .05, shake: 9 });
  g.fx.emit('ring', W / 2, 560, { r: 200, size: 150, life: .9, color: '#ffffff' });
  g.state.phase = 'win';
}

/* ------------------------------------------------------------------ drawing */
let skyGrad = null, glowGrad = null;
const BOKEH = [];
for (let i = 0; i < 16; i++) BOKEH.push({ x: R() * W, y: R() * H, r: rnd(8, 40), sp: rnd(6, 22), a: rnd(.03, .10) });

function backdrop(c) {
  if (!skyGrad) {
    skyGrad = c.createLinearGradient(0, 0, 0, H);
    skyGrad.addColorStop(0, '#050912'); skyGrad.addColorStop(.35, '#0a1630');
    skyGrad.addColorStop(.72, '#131033'); skyGrad.addColorStop(1, '#05070e');
    glowGrad = c.createRadialGradient(W / 2, 590, 30, W / 2, 590, 460);
    glowGrad.addColorStop(0, 'rgba(80,190,255,.18)'); glowGrad.addColorStop(.5, 'rgba(170,80,255,.10)');
    glowGrad.addColorStop(1, 'rgba(0,0,0,0)');
  }
  c.fillStyle = skyGrad; c.fillRect(0, 0, W, H);
  c.fillStyle = glowGrad; c.fillRect(0, 0, W, H);
  // parallax bokeh drifting up
  for (const b of BOKEH) {
    const y = (b.y - t * b.sp) % (H + 120);
    c.globalAlpha = b.a * (0.6 + Math.sin(t * .7 + b.x) * .4);
    c.fillStyle = '#9fe4ff';
    circle(c, b.x, y < 0 ? y + H + 120 : y, b.r);
    c.fill();
  }
  c.globalAlpha = 1;
}

function drawTubeBack(c, i, x, y, G) {
  c.save();
  // glass body
  const lg = c.createLinearGradient(x, 0, x + G.w, 0);
  lg.addColorStop(0, 'rgba(140,215,255,.13)');
  lg.addColorStop(.35, 'rgba(190,235,255,.05)');
  lg.addColorStop(.75, 'rgba(190,235,255,.07)');
  lg.addColorStop(1, 'rgba(120,200,255,.13)');
  c.fillStyle = lg;
  rr(c, x, y, G.w, G.h, G.w * .34); c.fill();
  c.restore();
}

function drawSlug(c, cx, cy, w, h, colIdx, o = {}) {
  const col = SLUG_COLS[colIdx];
  const x = cx - w / 2, y = cy - h / 2;
  const r2 = Math.min(10, h * .28, w * .3);
  const lg = c.createLinearGradient(x, y, x + w, y + h);
  lg.addColorStop(0, shade(col, 1.25));
  lg.addColorStop(.42, col);
  lg.addColorStop(1, shade(col, .62));
  c.save();
  if (o.alpha != null) c.globalAlpha = o.alpha;
  if (o.rot) { c.translate(cx, cy); c.rotate(o.rot); c.scale(o.sx || 1, o.sy || 1); c.translate(-cx, -cy); }
  c.fillStyle = lg;
  rr(c, x, y, w, h, r2); c.fill();
  c.strokeStyle = shade(col, .48); c.lineWidth = 1.4;
  rr(c, x, y, w, h, r2); c.stroke();
  // gloss
  c.fillStyle = 'rgba(255,255,255,.26)';
  rr(c, x + w * .12, y + h * .14, w * .26, h * .62, r2 * .7); c.fill();
  if (!o.dull) {
    // meniscus: a lighter curved surface on top
    c.fillStyle = hexA(shade(col, 1.5), .75);
    c.beginPath();
    c.ellipse(cx, y + 2.5, w * .44, h * .13, 0, 0, TAU);
    c.fill();
    c.strokeStyle = 'rgba(255,255,255,.5)'; c.lineWidth = 1.2;
    c.beginPath(); c.ellipse(cx, y + 1.6, w * .44, h * .12, 0, Math.PI * 1.05, Math.PI * 1.95); c.stroke();
  }
  c.restore();
}

function drawTube(c, i) {
  const G = geom[i], a = anim[i];
  const sh = Math.sin(t * 46) * a.shake * 7;
  const lift = a.lift * 8;
  const x = G.x + sh, y = G.y - lift;
  const tb = tubes[i];
  const sh4 = slugH(G);
  const isDone = tb.length === CAP && tb.every(cc => cc === tb[0]);

  // selection glow behind
  if (a.glow > .02 || isDone) {
    const col = isDone ? SLUG_COLS[tb[0]] : '#8fe9ff';
    c.save();
    c.globalAlpha = clamp(a.glow * .8, 0, .8);
    const rg = c.createRadialGradient(x + G.w / 2, y + G.h * .5, 10, x + G.w / 2, y + G.h * .5, G.w * 1.4);
    rg.addColorStop(0, hexA(col, .5)); rg.addColorStop(1, 'rgba(0,0,0,0)');
    c.fillStyle = rg;
    c.fillRect(x - G.w, y - G.w, G.w * 3, G.h + G.w * 2);
    c.restore();
  }

  drawTubeBack(c, i, x, y, G);

  // slugs, bottom first
  for (let s = 0; s < tb.length; s++) {
    const p = slotPos(i, s);
    const sx2 = x + G.w / 2;
    const sy2 = y + G.h - RIM - (s + 0.5) * sh4;
    const bob = (sel === i && s >= tb.length - 1) ? Math.sin(t * 7 + i) * 2 : 0;
    drawSlug(c, sx2, sy2 + bob, p.w, sh4 - 3, tb[s], { dull: s < tb.length - 1 });
  }

  // glass front
  c.save();
  c.strokeStyle = isDone ? hexA(SLUG_COLS[tb[0]], .85) : 'rgba(200,240,255,.55)';
  c.lineWidth = isDone ? 3.5 : 2.6;
  rr(c, x, y, G.w, G.h, G.w * .34); c.stroke();
  // inner highlight streak
  const hl = c.createLinearGradient(x, y, x + G.w * .5, y);
  hl.addColorStop(0, 'rgba(255,255,255,.42)'); hl.addColorStop(1, 'rgba(255,255,255,0)');
  c.strokeStyle = hl; c.lineWidth = 3.5;
  rr(c, x + 5, y + 8, G.w - 16, G.h - 16, G.w * .28); c.stroke();
  // rim
  c.strokeStyle = 'rgba(220,245,255,.28)'; c.lineWidth = 2;
  c.beginPath(); c.ellipse(x + G.w / 2, y + 4, G.w * .42, 6, 0, 0, TAU); c.stroke();
  c.restore();

  // selected tube: lift arrow / cursor ring
  if (sel === i) {
    c.save();
    const cx = x + G.w / 2;
    c.globalAlpha = .5 + Math.sin(t * 8) * .25;
    c.strokeStyle = '#ffe6a8'; c.lineWidth = 3;
    c.beginPath(); c.ellipse(cx, y - 16, G.w * .34, 7, 0, 0, TAU); c.stroke();
    c.restore();
  }
}

function draw() {}

function draw2(c) {
  backdrop(c);
  // marble shelf behind the tubes
  const sy = 300;
  const shelfG = c.createLinearGradient(0, sy, 0, sy + 600);
  shelfG.addColorStop(0, 'rgba(255,255,255,.045)'); shelfG.addColorStop(1, 'rgba(255,255,255,0)');
  c.fillStyle = shelfG;
  rr(c, 34, sy, W - 68, 610, 26); c.fill();
  c.strokeStyle = 'rgba(150,215,255,.10)'; c.lineWidth = 1.5;
  rr(c, 34, sy, W - 68, 610, 26); c.stroke();

  for (let i = 0; i < tubes.length; i++) drawTube(c, i);

  // flying slugs on top
  for (const f of fly) {
    if (f.t < 0) drawSlug(c, f.x0, f.y0, f.w, f.h, f.col, { alpha: .55 });
    else drawSlug(c, f.x, f.y, f.w, f.h, f.col, { rot: f.rot, sx: f.sx, sy: f.sy });
  }
  drawHUD(c);
}

function drawHUD(c) {
  // top plate
  c.fillStyle = 'rgba(6,12,24,.72)';
  rr(c, 16, 18, W - 32, 112, 20); c.fill();
  c.strokeStyle = 'rgba(140,215,255,.22)'; c.lineWidth = 1.6;
  rr(c, 16, 18, W - 32, 112, 20); c.stroke();

  g.text('LEVEL', 40, 52, { size: 18, color: '#8fd6ff', align: 'left' });
  const k = 1 + ui.levelPop * .18;
  c.save(); c.translate(40, 100); c.scale(k, k);
  g.text(`${levelIdx + 1}/${WINLVL}`, 0, 0, { size: 44, color: '#f2fbff', align: 'left', ink: '#04070f' });
  c.restore();

  // moves left (turns amber then red as it drains)
  const mf = clamp(movesLeft / 12, 0, 1);
  const mcol = movesLeft <= 3 ? '#ff5d7a' : (mf < .5 ? '#ffd23f' : '#a8f0ff');
  g.text('MOVES', W / 2, 52, { size: 18, color: '#8fd6ff', align: 'center' });
  const mk = 1 + ui.movePop * .14;
  c.save(); c.translate(W / 2, 100); c.scale(mk, mk);
  g.text(String(Math.max(0, movesLeft)), 0, 0, { size: 44, color: mcol, align: 'center', ink: '#04070f' });
  c.restore();

  g.text('SCORE', W - 40, 52, { size: 18, color: '#8fd6ff', align: 'right' });
  g.text(fmt(Math.round(score)), W - 40, 100, { size: 38, color: '#ffe6a8', align: 'right', ink: '#04070f' });

  // level pips
  for (let i = 0; i < WINLVL; i++) {
    const px = W / 2 - (WINLVL - 1) * 11 + i * 22, py = 148;
    c.beginPath();
    c.arc(px, py, 6, 0, TAU);
    c.fillStyle = i < levelIdx ? '#4ee06a' : (i === levelIdx ? '#ffe6a8' : 'rgba(255,255,255,.18)');
    c.fill();
    if (i === levelIdx) {
      c.strokeStyle = hexA('#ffe6a8', .6); c.lineWidth = 2;
      c.beginPath(); c.arc(px, py, 10 + Math.sin(t * 6) * 1.5, 0, TAU); c.stroke();
    }
  }

  // bottom hint
  const hint = sel >= 0 ? 'TAP A TUBE TO POUR' : 'TAP A TUBE TO LIFT THE TOP';
  c.fillStyle = 'rgba(6,12,24,.55)';
  rr(c, 60, 906, W - 120, 40, 14); c.fill();
  g.text(hint, W / 2, 933, { size: 18, color: sel >= 0 ? '#ffe6a8' : 'rgba(190,225,255,.72)', align: 'center', stroke: 0 });
}

const shade = (hex, k) => {
  const n = parseInt(hex.slice(1), 16);
  const f = v => clamp(Math.round(v * k), 0, 255).toString(16).padStart(2, '0');
  return '#' + f((n >> 16) & 255) + f((n >> 8) & 255) + f(n & 255);
};

/* ------------------------------------------------------------------ boot */
g.onReset = resetWorld;
g.onStart = () => music('puzzle');
resetWorld();
window.__g = g;
g.run(update, draw2);
